export const CORPUS_MAP = Object.fromEntries(CORPUS.map(c => [c.id, c]));

/* 取某一份；取不到返回 null（调用方要自己判） */
export function doc(id) { return CORPUS_MAP[id] || null; }

/* 按小节标题找：返回 [{id,title,head,text}] —— 给「依据」页按需检索用 */
export function sections(kw) {
  var q = String(kw || '');
  var out = [];
  CORPUS.forEach(function (c) {
    var parts = c.text.split(/^##\s+/m);
    parts.forEach(function (p, i) {
      if (i === 0) return;
      var nl = p.indexOf('\n');
      var head = (nl < 0 ? p : p.slice(0, nl)).trim();
      var bodyTx = (nl < 0 ? '' : p.slice(nl + 1)).trim();
      if (!q || head.indexOf(q) >= 0 || bodyTx.indexOf(q) >= 0) {
        out.push({ id: c.id, title: c.title, head: head, text: bodyTx });
      }
    });
  });
  return out;
}
